INSERT INTO components_shared_content_blocks VALUES(6,'Wren AI Web Credits & Pricing','Unlock AI-Powered Insights with a  Pay-as-You-Go Credit System',replace('<div class="overflow-x-auto rounded-xl border border-gray-200 bg-white p-8">\n  <table class="min-w-full divide-y divide-gray-200">\n    <thead>\n      <tr class="border-b border-gray-200">\n        <th class="px-6 py-3 font-medium text-blue-600 text-lg" style="text-align:left;">Feature</th>\n        <th class="px-6 py-3 font-medium text-blue-600 text-lg" style="text-align:left;">Web Credits &amp; Pricing</th>\n      </tr>\n    </thead>\n    <tbody class="divide-y divide-gray-100">\n      <tr class="border-b border-gray-200">\n        <td class="px-6 py-4 text-gray-800">Per Question + 4 free follow-ups</td>\n        <td class="px-6 py-4 text-gray-600">5 Credits</td>\n      </tr>\n     <tr class="border-b border-gray-200">\n        <td class="px-6 py-4 text-gray-800">Per Additional Follow-ups</td>\n        <td class="px-6 py-4 text-gray-600">2 Credits</td>\n      </tr>\n      <tr class="border-b border-gray-200">\n        <td class="px-6 py-4 text-gray-800">Spreadsheet</td>\n        <td class="px-6 py-4 text-gray-600">1 Credit Per execution</td>\n      </tr>\n     <tr class="border-b border-gray-200">\n        <td class="px-6 py-4 text-gray-800">\n          Chart\n          <div class="text-xs text-gray-500">(Only charge for the initial generation)</div>\n        </td>\n        <td class="px-6 py-4 text-gray-600">1 Credit Per initial Generation</td>\n      </tr>\n     <tr class="border-b border-gray-200">\n        <td class="px-6 py-4 text-gray-800">\n          Importing Data from Services\n          <div class="text-xs text-gray-500">(Only required for boilerplate data sync)</div>\n        </td>\n        <td class="px-6 py-4 text-gray-600">1 Credit Per 2000 Rows</td>\n      </tr>\n    </tbody>\n  </table>\n</div>\n','\n',char(10)),'cards','left',NULL,NULL);
INSERT INTO components_shared_content_blocks VALUES(8,'Embedded AI  API Pricing','Unlock AI-Powered Insights with a  Pay-as-You-Go API Endpoints*',replace('<div class="overflow-x-auto rounded-xl border border-gray-200 bg-white p-8">\n  <table class="min-w-full divide-y divide-gray-200 text-left">\n    <thead>\n      <tr class="border-b border-gray-200">\n        <th class="px-6 py-3 font-medium text-blue-600 text-lg" style="text-align:left;">Feature</th>\n        <th class="px-6 py-3 font-medium text-blue-600 text-lg" style="text-align:left;">API Credits &amp; Pricing</th>\n      </tr>\n    </thead>\n    <tbody class="divide-y divide-gray-100">\n     <tr class="border-b border-gray-200">\n        <td class="px-6 py-4 text-gray-800">\n          Ask Question\n          <div class="text-xs text-gray-500">(/api/v1/ask)</div>\n        </td>\n        <td class="px-6 py-4 text-gray-600">$0.18 per request</td>\n      </tr>\n     <tr class="border-b border-gray-200">\n        <td class="px-6 py-4 text-gray-800">\n          Ask Question - Streaming\n          <div class="text-xs text-gray-500">(/api/v1/stream/ask)</div>\n        </td>\n        <td class="px-6 py-4 text-gray-600">$0.18 per request</td>\n      </tr>\n    <tr class="border-b border-gray-200">\n        <td class="px-6 py-4 text-gray-800">\n          Generate SQL\n          <div class="text-xs text-gray-500">(/api/v1/generate_sql)</div>\n        </td>\n        <td class="px-6 py-4 text-gray-600">$0.15 per request</td>\n      </tr>\n     <tr class="border-b border-gray-200">\n        <td class="px-6 py-4 text-gray-800">\n          Generate SQL - Streaming\n          <div class="text-xs text-gray-500">(/api/v1/stream/generate_sql)</div>\n        </td>\n        <td class="px-6 py-4 text-gray-600">$0.15 per request</td>\n      </tr>\n     <tr class="border-b border-gray-200">\n        <td class="px-6 py-4 text-gray-800">\n          Generate Chart\n          <div class="text-xs text-gray-500">(/api/v1/generate_vega_chart)</div>\n        </td>\n        <td class="px-6 py-4 text-gray-600">$0.03 per request</td>\n      </tr>\n     <tr class="border-b border-gray-200">\n        <td class="px-6 py-4 text-gray-800">\n          Generate Summary\n          <div class="text-xs text-gray-500">(/api/v1/summary)</div>\n        </td>\n        <td class="px-6 py-4 text-gray-600">$0.03 per request</td>\n      </tr>\n    </tbody>\n  </table>\n</div>\n','\n',char(10)),NULL,NULL,'[{"type":"paragraph","children":[{"type":"text","text":"You must subscribe Essential Plan & Above to enable AI API"}]}]',NULL);
INSERT INTO components_shared_content_blocks VALUES(111,'Wren AI Web Credits & Pricing','Unlock AI-Powered Insights with a  Pay-as-You-Go Credit System',replace('<div class="overflow-x-auto rounded-xl border border-gray-200 bg-white p-8">\n  <table class="min-w-full divide-y divide-gray-200">\n    <thead>\n      <tr class="border-b border-gray-200">\n        <th class="px-6 py-3 font-medium text-blue-600 text-lg" style="text-align:left;">Feature</th>\n        <th class="px-6 py-3 font-medium text-blue-600 text-lg" style="text-align:left;">Web Credits &amp; Pricing</th>\n      </tr>\n    </thead>\n    <tbody class="divide-y divide-gray-100">\n      <tr class="border-b border-gray-200">\n        <td class="px-6 py-4 text-gray-800">Per Question + 4 free follow-ups</td>\n        <td class="px-6 py-4 text-gray-600">5 Credits</td>\n      </tr>\n     <tr class="border-b border-gray-200">\n        <td class="px-6 py-4 text-gray-800">Per Additional Follow-ups</td>\n        <td class="px-6 py-4 text-gray-600">2 Credits</td>\n      </tr>\n      <tr class="border-b border-gray-200">\n        <td class="px-6 py-4 text-gray-800">Spreadsheet</td>\n        <td class="px-6 py-4 text-gray-600">1 Credit Per execution</td>\n      </tr>\n     <tr class="border-b border-gray-200">\n        <td class="px-6 py-4 text-gray-800">\n          Chart\n          <div class="text-xs text-gray-500">(Only charge for the initial generation)</div>\n        </td>\n        <td class="px-6 py-4 text-gray-600">1 Credit Per initial Generation</td>\n      </tr>\n     <tr class="border-b border-gray-200">\n        <td class="px-6 py-4 text-gray-800">\n          Importing Data from Services\n          <div class="text-xs text-gray-500">(Only required for boilerplate data sync)</div>\n        </td>\n        <td class="px-6 py-4 text-gray-600">1 Credit Per 2000 Rows</td>\n      </tr>\n    </tbody>\n  </table>\n</div>\n','\n',char(10)),'cards','left',NULL,NULL);
INSERT INTO components_shared_content_blocks VALUES(112,'Embedded AI  API Pricing','Unlock AI-Powered Insights with a  Pay-as-You-Go API Endpoints*',replace('<div class="overflow-x-auto rounded-xl border border-gray-200 bg-white p-8">\n  <table class="min-w-full divide-y divide-gray-200 text-left">\n    <thead>\n      <tr class="border-b border-gray-200">\n        <th class="px-6 py-3 font-medium text-blue-600 text-lg" style="text-align:left;">Feature</th>\n        <th class="px-6 py-3 font-medium text-blue-600 text-lg" style="text-align:left;">API Credits &amp; Pricing</th>\n      </tr>\n    </thead>\n    <tbody class="divide-y divide-gray-100">\n     <tr class="border-b border-gray-200">\n        <td class="px-6 py-4 text-gray-800">\n          Ask Question\n          <div class="text-xs text-gray-500">(/api/v1/ask)</div>\n        </td>\n        <td class="px-6 py-4 text-gray-600">$0.18 per request</td>\n      </tr>\n     <tr class="border-b border-gray-200">\n        <td class="px-6 py-4 text-gray-800">\n          Ask Question - Streaming\n          <div class="text-xs text-gray-500">(/api/v1/stream/ask)</div>\n        </td>\n        <td class="px-6 py-4 text-gray-600">$0.18 per request</td>\n      </tr>\n    <tr class="border-b border-gray-200">\n        <td class="px-6 py-4 text-gray-800">\n          Generate SQL\n          <div class="text-xs text-gray-500">(/api/v1/generate_sql)</div>\n        </td>\n        <td class="px-6 py-4 text-gray-600">$0.15 per request</td>\n      </tr>\n     <tr class="border-b border-gray-200">\n        <td class="px-6 py-4 text-gray-800">\n          Generate SQL - Streaming\n          <div class="text-xs text-gray-500">(/api/v1/stream/generate_sql)</div>\n        </td>\n        <td class="px-6 py-4 text-gray-600">$0.15 per request</td>\n      </tr>\n     <tr class="border-b border-gray-200">\n        <td class="px-6 py-4 text-gray-800">\n          Generate Chart\n          <div class="text-xs text-gray-500">(/api/v1/generate_vega_chart)</div>\n        </td>\n        <td class="px-6 py-4 text-gray-600">$0.03 per request</td>\n      </tr>\n     <tr class="border-b border-gray-200">\n        <td class="px-6 py-4 text-gray-800">\n          Generate Summary\n          <div class="text-xs text-gray-500">(/api/v1/summary)</div>\n        </td>\n        <td class="px-6 py-4 text-gray-600">$0.03 per request</td>\n      </tr>\n    </tbody>\n  </table>\n</div>\n','\n',char(10)),NULL,NULL,'[{"type":"paragraph","children":[{"type":"text","text":"You must subscribe Essential Plan & Above to enable AI API"}]}]',NULL);
INSERT INTO components_shared_content_blocks VALUES(113,'Ask Questions in Your Language. Get Trusted Answers. Faster.','Wren AI’s Intelligent AI Modeling connects your business metrics, relationships, and data definitions into one consistent modeling framework. It ensures every query, dashboard, and report delivers fast, governed, and explainable insights.',replace('<div class="space-y-6">\n  <!-- Interactive Natural Language Querying -->\n  <div class="border-b border-gray-200 flex gap-4 items-start py-3">\n    <div class="text-blue-600 text-xl">\n      <svg class="w-6 h-6 text-blue-600" aria-hidden="true" xmlns="http://www.w3.org/2000/svg" width="24" height="24" fill="none" viewBox="0 0 24 24">\n  <path stroke="currentColor" stroke-linecap="round" stroke-width="2" d="M5 7h14M5 12h14M5 17h14"/>\n</svg>\n\n    </div>\n    <div>\n      <h3 class="font-semibold text-gray-900">\n        Interactive Natural Language Querying — In Your Language.\n      </h3>\n      <p class="text-gray-600 text-sm mt-1">\n        Ask: “Show revenue from premium customers in Q2” → Wren AI returns accurate insights instantly — no SQL required\n      </p>\n    </div>\n  </div>\n\n  <!-- Semantic Modeling -->\n  <div class="border-b border-gray-200 flex gap-5 items-start py-3">\n    <div class="text-blue-600 text-xl">\n     <svg width="18" height="20" viewBox="0 0 18 20" fill="none" xmlns="http://www.w3.org/2000/svg">\n<path d="M7 0C7.5523 0 8 0.44772 8 1V5C8 5.55228 7.5523 6 7 6H5V8H10V7C10 6.44772 10.4477 6 11 6H17C17.5523 6 18 6.44772 18 7V11C18 11.5523 17.5523 12 17 12H11C10.4477 12 10 11.5523 10 11V10H5V16H10V15C10 14.4477 10.4477 14 11 14H17C17.5523 14 18 14.4477 18 15V19C18 19.5523 17.5523 20 17 20H11C10.4477 20 10 19.5523 10 19V18H4C3.44772 18 3 17.5523 3 17V6H1C0.44772 6 0 5.55228 0 5V1C0 0.44772 0.44772 0 1 0H7ZM16 16H12V18H16V16ZM16 8H12V10H16V8ZM6 2H2V4H6V2Z" fill="#2F54EB"/>\n</svg>\n\n    </div>\n    <div>\n      <h3 class="font-semibold text-gray-900">Semantic Modeling</h3>\n      <p class="text-gray-600 text-sm mt-1">\n        Wren AI’s semantic modeling ensures SQL accuracy, consistent definitions, and reliable, business-aligned insights for teams.\n      </p>\n    </div>\n  </div>\n\n  <!-- Embedded-Ready -->\n  <div class="border-b border-gray-200 flex gap-5 items-start py-3">\n    <div class="text-blue-600 text-xl">\n      <svg width="20" height="18" viewBox="0 0 20 18" fill="none" xmlns="http://www.w3.org/2000/svg">\n<path d="M2 5H18V2H2V5ZM12 16V7H8V16H12ZM14 16H18V7H14V16ZM6 16V7H2V16H6ZM1 0H19C19.5523 0 20 0.44772 20 1V17C20 17.5523 19.5523 18 19 18H1C0.44772 18 0 17.5523 0 17V1C0 0.44772 0.44772 0 1 0Z" fill="#2F54EB"/>\n</svg>\n\n    </div>\n    <div>\n      <h3 class="font-semibold text-gray-900">Embedded-Ready</h3>\n      <p class="text-gray-600 text-sm mt-1">\n        Embed Wren AI’s API to deliver branded conversational analytics with seamless AI-powered insights inside your UI.\n      </p>\n    </div>\n  </div>\n\n  <!-- Feedback Loop -->\n  <div class="border-b border-gray-200 flex gap-5 items-start py-3">\n    <div class="text-blue-600 text-xl">\n     <svg width="22" height="20" viewBox="0 0 22 20" fill="none" xmlns="http://www.w3.org/2000/svg">\n<path d="M18.3788 13.1056C19.9258 9.44204 18.5373 5.11425 15.0042 3.07444C12.4511 1.6004 9.4232 1.69359 7.03452 3.05554L6.04216 1.31873C9.028 -0.383669 12.8128 -0.50016 16.0042 1.34239C20.4949 3.93507 22.2139 9.48474 20.1217 14.1119L21.4635 14.8866L17.2984 17.1007L17.1334 12.3866L18.3788 13.1056ZM3.62961 6.89962C2.08263 10.5632 3.47116 14.891 7.00421 16.9308C9.5573 18.4048 12.5851 18.3117 14.9737 16.9498L15.9661 18.6866C12.9803 20.3889 9.1956 20.5054 6.00421 18.6629C1.51357 16.0702 -0.205433 10.5205 1.88672 5.89336L0.544922 5.11867L4.70999 2.90457L4.87505 7.61867L3.62961 6.89962ZM12.4184 12.831L9.59 10.0026L6.76157 12.831L5.34736 11.4168L9.59 7.17422L12.4184 10.0026L15.2469 7.17422L16.6611 8.58844L12.4184 12.831Z" fill="#2F54EB"/>\n</svg>\n\n    </div>\n    <div>\n      <h3 class="font-semibold text-gray-900">Feedback Loop</h3>\n      <p class="text-gray-600 text-sm mt-1">\n        Wren AI’s feedback loop learns from user corrections, adapting to business logic for continuous accuracy.\n      </p>\n    </div>\n  </div>\n\n  <!-- Footer text -->\n  <div class="pt-10 text-sm">\n    Ask questions naturally, in your language, and get accurate answers instantly.\n  </div>\n</div>\n','\n',char(10)),'cards','left',NULL,'Semantic Modeling + Feedback Loop');
INSERT INTO components_shared_content_blocks VALUES(129,'Secure Data Access  for Every AI Agent.','Wren AI supports the MCP protocol, enabling secure collaboration with other AI agents and safe database queries, ensuring governed data access in MCP-compatible environments.',replace('<div class="space-y-6">\n  <div class="border-b border-gray-200 flex gap-4 items-start py-3">\n    <div class="text-blue-600 text-xl">\n      <svg width="20" height="20" viewBox="0 0 20 20" fill="none" xmlns="http://www.w3.org/2000/svg">\n<path d="M16.3638 13.5356L14.9496 12.1214L16.3638 10.7072C18.3164 8.75456 18.3164 5.58872 16.3638 3.6361C14.4112 1.68347 11.2453 1.68347 9.2927 3.6361L7.87849 5.05031L6.46428 3.6361L7.87849 2.22188C10.6122 -0.511787 15.0443 -0.511787 17.778 2.22188C20.5117 4.95555 20.5117 9.38766 17.778 12.1214L16.3638 13.5356ZM13.5353 16.3641L12.1211 17.7783C9.3875 20.5119 4.95531 20.5119 2.22164 17.7783C-0.512031 15.0446 -0.512031 10.6124 2.22164 7.87874L3.63585 6.46452L5.05007 7.87874L3.63585 9.29296C1.68323 11.2456 1.68323 14.4114 3.63585 16.3641C5.58847 18.3167 8.7543 18.3167 10.7069 16.3641L12.1211 14.9498L13.5353 16.3641ZM12.8282 5.75742L14.2425 7.17163L7.17139 14.2427L5.75717 12.8285L12.8282 5.75742Z" fill="#2F54EB"/>\n</svg>\n\n    </div>\n    <div>\n      <h3 class="font-semibold text-gray-900">\n       MCP Protocol Support.\n      </h3>\n      <p class="text-gray-600 text-sm mt-1">\n       Connect Wren AI with other AI agents\n      </p>\n    </div>\n  </div>\n\n  <div class="border-b border-gray-200 flex gap-5 items-start py-3">\n    <div class="text-blue-600 text-xl">\n     <svg width="19" height="21" viewBox="0 0 19 21" fill="none" xmlns="http://www.w3.org/2000/svg">\n<path d="M15.0003 11V12C15.0003 14.7696 14.3364 17.445 13.0853 19.8455L12.8585 20.2663L11.1116 19.2924C12.2716 17.2115 12.9211 14.8817 12.9935 12.4559L13.0003 12V11H15.0003ZM9.0003 8H11.0003V12L10.9948 12.3787C10.9153 15.1495 9.9645 17.7731 8.3038 19.928L8.073 20.2189L6.52406 18.9536C8.0408 17.0969 8.9145 14.8017 8.9943 12.3663L9.0003 12V8ZM10.0003 4C12.7617 4 15.0003 6.23858 15.0003 9H13.0003C13.0003 7.34315 11.6571 6 10.0003 6C8.3434 6 7.00025 7.34315 7.00025 9V12C7.00025 14.2354 6.1806 16.3444 4.72928 17.9768L4.51767 18.2067L3.06955 16.8273C4.23328 15.6056 4.92099 14.0118 4.99381 12.3027L5.00025 12V9C5.00025 6.23858 7.23883 4 10.0003 4ZM10.0003 0C14.9708 0 19.0003 4.02944 19.0003 9V12C19.0003 13.6979 18.7985 15.3699 18.4035 16.9903L18.2647 17.5285L16.3349 17.0032C16.726 15.5662 16.9475 14.0808 16.9919 12.5684L17.0003 12V9C17.0003 5.13401 13.8662 2 10.0003 2C8.4279 2 6.97663 2.51841 5.80805 3.39364L4.38308 1.96769C5.92267 0.73631 7.87547 0 10.0003 0ZM2.96794 3.38282L4.39389 4.8078C3.5635 5.91652 3.0543 7.27971 3.00431 8.7593L2.99961 8.999L3.00378 11C3.00378 12.1195 2.73991 13.2026 2.24263 14.1772L2.08648 14.4663L0.349609 13.4747C0.728889 12.8103 0.950769 12.0681 0.995389 11.2924L1.00378 11L1.00361 9C1.00025 6.87522 1.73656 4.92242 2.96794 3.38282Z" fill="#2F54EB"/>\n</svg>\n\n    </div>\n    <div>\n      <h3 class="font-semibold text-gray-900">Secure Database Access</h3>\n      <p class="text-gray-600 text-sm mt-1">\n        Enforce role-based permissions and governance\n      </p>\n    </div>\n  </div>\n\n  <div class="border-b border-gray-200 flex gap-5 items-start py-3">\n    <div class="text-blue-600 text-xl">\n  <svg width="18" height="19" viewBox="0 0 18 19" fill="none" xmlns="http://www.w3.org/2000/svg">\n<path d="M2 9.5C2 9.8134 2.46101 10.3584 3.53047 10.8931C4.91405 11.5849 6.87677 12 9 12C11.1232 12 13.0859 11.5849 14.4695 10.8931C15.539 10.3584 16 9.8134 16 9.5V7.3287C14.35 8.3482 11.8273 9 9 9C6.17273 9 3.64996 8.3482 2 7.3287V9.5ZM16 12.3287C14.35 13.3482 11.8273 14 9 14C6.17273 14 3.64996 13.3482 2 12.3287V14.5C2 14.8134 2.46101 15.3584 3.53047 15.8931C4.91405 16.5849 6.87677 17 9 17C11.1232 17 13.0859 16.5849 14.4695 15.8931C15.539 15.3584 16 14.8134 16 14.5V12.3287ZM0 14.5V4.5C0 2.01472 4.02944 0 9 0C13.9706 0 18 2.01472 18 4.5V14.5C18 16.9853 13.9706 19 9 19C4.02944 19 0 16.9853 0 14.5ZM9 7C11.1232 7 13.0859 6.58492 14.4695 5.89313C15.539 5.3584 16 4.81342 16 4.5C16 4.18658 15.539 3.6416 14.4695 3.10687C13.0859 2.41508 11.1232 2 9 2C6.87677 2 4.91405 2.41508 3.53047 3.10687C2.46101 3.6416 2 4.18658 2 4.5C2 4.81342 2.46101 5.3584 3.53047 5.89313C4.91405 6.58492 6.87677 7 9 7Z" fill="#2F54EB"/>\n</svg>\n\n\n    </div>\n    <div>\n      <h3 class="font-semibold text-gray-900">Bring Analytics Anywhere</h3>\n      <p class="text-gray-600 text-sm mt-1">\n        Extend SQL + semantic querying into agent workflows\n      </p>\n    </div>\n  </div>\n\n  <div class="border-b border-gray-200 flex gap-5 items-start py-3">\n    <div class="text-blue-600 text-xl">\n   <svg width="24" height="20" viewBox="0 0 24 20" fill="none" xmlns="http://www.w3.org/2000/svg">\n<path d="M5.23379 5.72989C6.65303 3.48625 9.15342 2 12.0002 2C14.847 2 17.3474 3.48625 18.7667 5.72989L20.4569 4.66071C18.6865 1.86199 15.5612 0 12.0002 0C8.43928 0 5.31393 1.86199 3.54356 4.66071L5.23379 5.72989ZM12.0002 18C9.15342 18 6.65303 16.5138 5.23379 14.2701L3.54356 15.3393C5.31393 18.138 8.43928 20 12.0002 20C15.5612 20 18.6865 18.138 20.4569 15.3393L18.7667 14.2701C17.3474 16.5138 14.847 18 12.0002 18ZM12 10C13.6569 10 15 8.6569 15 7C15 5.34315 13.6569 4 12 4C10.3431 4 9 5.34315 9 7C9 8.6569 10.3431 10 12 10ZM12 11C14.2091 11 16 12.7909 16 15H8C8 12.7909 9.79086 11 12 11ZM6 10C6 11.6569 4.65685 13 3 13C1.34315 13 0 11.6569 0 10C0 8.3431 1.34315 7 3 7C4.65685 7 6 8.3431 6 10ZM21 13C22.6569 13 24 11.6569 24 10C24 8.3431 22.6569 7 21 7C19.3431 7 18 8.3431 18 10C18 11.6569 19.3431 13 21 13Z" fill="#2F54EB"/>\n</svg>\n\n\n    </div>\n    <div>\n      <h3 class="font-semibold text-gray-900">Seamless Collaboration</h3>\n      <p class="text-gray-600 text-sm mt-1">\n        Surface insights in Slack, Teams, or custom MCP apps\n      </p>\n    </div>\n  </div>\n\n  <!-- Footer text -->\n  <div class="pt-10 text-sm">\n   Wren AI ensures your data stays secure while empowering every AI agent with trusted analytics.\n  </div>\n</div>\n','\n',char(10)),'cards','right','[{"type":"paragraph","children":[{"type":"text","text":""}]}]','MCP Connectivity & Secure Agent Collaboration');
INSERT INTO components_shared_content_blocks VALUES(146,'Connect to Your Data. Anywhere It Lives.','Wren AI integrates natively with your databases, warehouses, and files like CSV, while syncing seamlessly with tools such as dbt. Use your existing data infrastructure to power analytics and AI without rebuilding pipelines.',replace('<div class="space-y-6">\n  <div class="border-b border-gray-200 flex gap-4 items-start py-3">\n    <div class="text-blue-600 text-xl">\n<svg width="18" height="19" viewBox="0 0 18 19" fill="none" xmlns="http://www.w3.org/2000/svg">\n<path d="M2 9.5C2 9.8134 2.46101 10.3584 3.53047 10.8931C4.91405 11.5849 6.87677 12 9 12C11.1232 12 13.0859 11.5849 14.4695 10.8931C15.539 10.3584 16 9.8134 16 9.5V7.3287C14.35 8.3482 11.8273 9 9 9C6.17273 9 3.64996 8.3482 2 7.3287V9.5ZM16 12.3287C14.35 13.3482 11.8273 14 9 14C6.17273 14 3.64996 13.3482 2 12.3287V14.5C2 14.8134 2.46101 15.3584 3.53047 15.8931C4.91405 16.5849 6.87677 17 9 17C11.1232 17 13.0859 16.5849 14.4695 15.8931C15.539 15.3584 16 14.8134 16 14.5V12.3287ZM0 14.5V4.5C0 2.01472 4.02944 0 9 0C13.9706 0 18 2.01472 18 4.5V14.5C18 16.9853 13.9706 19 9 19C4.02944 19 0 16.9853 0 14.5ZM9 7C11.1232 7 13.0859 6.58492 14.4695 5.89313C15.539 5.3584 16 4.81342 16 4.5C16 4.18658 15.539 3.6416 14.4695 3.10687C13.0859 2.41508 11.1232 2 9 2C6.87677 2 4.91405 2.41508 3.53047 3.10687C2.46101 3.6416 2 4.18658 2 4.5C2 4.81342 2.46101 5.3584 3.53047 5.89313C4.91405 6.58492 6.87677 7 9 7Z" fill="#2F54EB"/>\n</svg>\n\n\n    </div>\n    <div>\n      <h3 class="font-semibold text-gray-900">\n      Direct connections to leading databases and warehouses\n      </h3>\n    </div>\n  </div>\n\n  <div class="border-b border-gray-200 flex gap-5 items-start py-3">\n    <div class="text-blue-600 text-xl">\n<svg width="20" height="18" viewBox="0 0 20 18" fill="none" xmlns="http://www.w3.org/2000/svg">\n<path d="M1 0C0.44772 0 0 0.44772 0 1V17C0 17.5523 0.44772 18 1 18H19C19.5523 18 20 17.5523 20 17V1C20 0.44772 19.5523 0 19 0H