L,'Data Connectivity & Integrations');
INSERT INTO components_shared_content_blocks VALUES(171,'Ask Questions,  Get Charts without  the BI Learning Curve','Skip complex BI tools. Wren AI lets you ask questions, generate charts, schedule refreshes, and manage databases with natural language in a familiar spreadsheet view.',replace('<div class="space-y-6">\n  <div class="border-b border-gray-200 flex gap-4 items-start py-3">\n    <div class="text-blue-600 text-xl">\n<svg width="18" height="17" viewBox="0 0 18 17" fill="none" xmlns="http://www.w3.org/2000/svg">\n<path d="M0 0H18V2H0V0ZM0 15H18V17H0V15ZM0 10H18V12H0V10ZM0 5H18V7H0V5Z" fill="#2F54EB"/>\n</svg>\n\n\n\n    </div>\n    <div>\n      <h3 class="font-semibold text-gray-900">\n     Ask in plain English to create instant charts and dashboards\n      </h3>\n    </div>\n  </div>\n\n  <div class="border-b border-gray-200 flex gap-5 items-start py-3">\n    <div class="text-blue-600 text-xl">\n<svg width="20" height="20" viewBox="0 0 20 20" fill="none" xmlns="http://www.w3.org/2000/svg">\n<path d="M19.3126 9.17524L17.8984 10.5894L17.1913 9.88234L12.9486 14.1249L12.2415 17.6605L10.8273 19.0747L6.58466 14.832L1.63492 19.7818L0.220703 18.3676L5.17045 13.4178L0.927813 9.17524L2.34202 7.76101L5.87756 7.0539L10.1202 2.81126L9.4131 2.10416L10.8273 0.689941L19.3126 9.17524Z" fill="#2F54EB"/>\n</svg>\n\n\n    </div>\n    <div>\n      <h3 class="font-semibold text-gray-900">Pin reports and schedule cache refreshes for consistent performance</h3>\n    </div>\n  </div>\n\n  <div class="border-b border-gray-200 flex gap-5 items-start py-3">\n    <div class="text-blue-600 text-xl">\n<svg width="20" height="18" viewBox="0 0 20 18" fill="none" xmlns="http://www.w3.org/2000/svg">\n<path d="M1 0C0.44772 0 0 0.44772 0 1V17C0 17.5523 0.44772 18 1 18H19C19.5523 18 20 17.5523 20 17V1C20 0.44772 19.5523 0 19 0H1ZM6 2V5H2V2H6ZM2 11V7H6V11H2ZM2 13H6V16H2V13ZM8 13H18V16H8V13ZM18 11H8V7H18V11ZM18 2V5H8V2H18Z" fill="#2F54EB"/>\n</svg>\n\n\n\n\n    </div>\n    <div>\n      <h3 class=