8 16.9853 13.9706 19 9 19C4.02944 19 0 16.9853 0 14.5ZM9 7C11.1232 7 13.0859 6.58492 14.4695 5.89313C15.539 5.3584 16 4.81342 16 4.5C16 4.18658 15.539 3.6416 14.4695 3.10687C13.0859 2.41508 11.1232 2 9 2C6.87677 2 4.91405 2.41508 3.53047 3.10687C2.46101 3.6416 2 4.18658 2 4.5C2 4.81342 2.46101 5.3584 3.53047 5.89313C4.91405 6.58492 6.87677 7 9 7Z" fill="#2F54EB"/>\n</svg>\n\n\n    </div>\n    <div>\n      <h3 class="font-semibold text-gray-900">Bring Analytics Anywhere</h3>\n      <p class="text-gray-600 text-sm mt-1">\n        Extend SQL + semantic querying into agent workflows\n      </p>\n    </div>\n  </div>\n\n  <div class="border-b border-gray-200 flex gap-5 items-start py-3">\n    <div class="text-blue-600 text-xl">\n   <svg width="24" height="20" viewBox="0 0 24 20" fill="none" xmlns="http://www.w3.org/2000/svg">\n<path d="M5.23379 5.72989C6.65303 3.48625 9.15342 2 12.0002 2C14.847 2 17.3474 3.48625 18.7667 5.72989L20.4569 4.66071C18.6865 1.86199 15.5612 0 12.0002 0C8.43928 0 5.31393 1.86199 3.54356 4.66071L5.23379 5.72989ZM12.0002 18C9.15342 18 6.65303 16.5138 5.23379 14.2701L3.54356 15.3393C5.31393 18.138 8.43928 20 12.0002 20C15.5612 20 18.6865 18.138 20.4569 15.3393L18.7667 14.2701C17.3474 16.5138 14.847 18 12.0002 18ZM12 10C13.6569 10 15 8.6569 15 7C15 5.34315 13.6569 4 12 4C10.3431 4 9 5.34315 9 7C9 8.6569 10.3431 10 12 10ZM12 11C14.2091 11 16 12.7909 16 15H8C8 12.7909 9.79086 11 12 11ZM6 10C6 11.6569 4.65685 13 3 13C1.34315 13 0 11.6569 0 10C0 8.3431 1.34315 7 3 7C4.65685 7 6 8.3431 6 10ZM21 13C22.6569 13 24 11.6569 24 10C24 8.3431 22.6569 7 21 7C19.3431 7 18 8.3431 18 10C18 11.6569 19.3431 13 21 13Z" fill="#2F54EB"/>\n</svg>\n\n\n    </div>\n    <div>\n      <h3 class="font-semibold text-gray-900">Seamless Collaboration</h3>\n      <p class="text-gray-600 text-sm mt-1">\n        Surface insights in Slack, Teams, or custom MCP apps\n      </p>\n    </div>\n  </div>\n\n  <!-- Footer text -->\n  <div class="pt-10 text-sm">\n   Wren AI ensures your data stays secure while empowering every AI agent with trusted analytics.\n  </div>\n</div>\n','\n',char(10)),'cards','right','[{"type":"paragraph","children":[{"type":"text","text":""}]}]','MCP Connectivity & Secure Agent Collaboration');
INSERT INTO components_shared_content_blocks VALUES(229,'Connect to Your Data. Anywhere It Lives.','Wren AI integrates natively with your databases, warehouses, and files like CSV, while syncing seamlessly with tools such as dbt. Use your existing data infrastructure to power analytics and AI without rebuilding pipelines.',replace('<div class="space-y-6">\n  <div class="border-b border-gray-200 flex gap-4 items-start py-3">\n    <div class="text-blue-600 text-xl">\n<svg width="18" height="19" viewBox="0 0 18 19" fill="none" xmlns="http://www.w3.org/2000/svg">\n<path d="M2 9.5C2 9.8134 2.46101 10.3584 3.53047 10.8931C4.91405 11.5849 6.87677 12 9 12C11.1232 12 13.0859 11.5849 14.4695 10.8931C15.539 10.3584 16 9.8134 16 9.5V7.3287C14.35 8.3482 11.8273 9 9 9C6.17273 9 3.64996 8.3482 2 7.3287V9.5ZM16 12.3287C14.35 13.3482 11.8273 14 9 14C6.17273 14 3.64996 13.3482 2 12.3287V14.5C2 14.8134 2.46101 15.3584 3.53047 15.8931C4.91405 16.5849 6.87677 17 9 17C11.1232 17 13.0859 16.5849 14.4695 15.8931C15.539 15.3584 16 14.8134 16 14.5V12.3287ZM0 14.5V4.5C0 2.01472 4.02944 0 9 0C13.9706 0 18 2.01472 18 4.5V14.5C18 16.9853 13.9706 19 9 19C4.02944 19 0 16.9853 0 14.5ZM9 7C11.1232 7 13.0859 6.58492 14.4695 5.89313C15.539 5.3584 16 4.81342 16 4.5C16 4.18658 15.539 3.6416 14.4695 3.10687C13.0859 2.41508 11.1232 2 9 2C6.87677 2 4.91405 2.41508 3.53047 3.10687C2.46101 3.6416 2 4.18658 2 4.5C2 4.81342 2.46101 5.3584 3.53047 5.89313C4.91405 6.58492 6.87677 7 9 7Z" fill="#2F54EB"/>\n</svg>\n\n\n    </div>\n    <div>\n      <h3 class="font-semibold text-gray-900">\n      Direct connections to leading databases and warehouses\n      </h3>\n    </div>\n  </div>\n\n  <div class="border-b border-gray-200 flex gap-5 items-start py-3">\n    <div class="text-blue-600 text-xl">\n<svg width="20" height="18" viewBox="0 0 20 18" fill="none" xmlns="http://www.w3.org/2000/svg">\n<path d="M1 0C0.44772 0 0 0.44772 0 1V17C0 17.5523 0.44772 18 1 18H19C19.5523 18 20 17.5523 20 17V1C20 0.44772 19.5523 0 19 0H1ZM6 2V5H2V2H6ZM2 11V7H6V11H2ZM2 13H6V16H2V13ZM8 13H18V16H8V13ZM18 11H8V7H18V11ZM18 2V5H8V2H18Z" fill="#2F54EB"/>\n</svg>\n\n    </div>\n    <div>\n      <h3 class="font-semibold text-gray-900">Support for files like CSV and Google Sheets</h3>\n    </div>\n  </div>\n\n  <div class="border-b border-gray-200 flex gap-5 items-start py-3">\n    <div class="text-blue-600 text-xl">\n<svg width="20" height="20" viewBox="0 0 20 20" fill="none" xmlns="http://www.w3.org/2000/svg">\n<path d="M16.3638 13.5353L14.9496 12.1211L16.3638 10.7069C18.3164 8.75432 18.3164 5.58848 16.3638 3.63586C14.4112 1.68323 11.2453 1.68323 9.2927 3.63586L7.87849 5.05007L6.46428 3.63586L7.87849 2.22164C10.6122 -0.512031 15.0443 -0.512031 17.778 2.22164C20.5117 4.95531 20.5117 9.38742 17.778 12.1211L16.3638 13.5353ZM13.5353 16.3638L12.1211 17.778C9.3875 20.5116 4.95531 20.5116 2.22164 17.778C-0.512031 15.0443 -0.512031 10.6121 2.22164 7.8785L3.63585 6.46428L5.05007 7.8785L3.63585 9.29272C1.68323 11.2453 1.68323 14.4111 3.63585 16.3638C5.58847 18.3164 8.7543 18.3164 10.7069 16.3638L12.1211 14.9495L13.5353 16.3638ZM12.8282 5.75718L14.2425 7.17139L7.17139 14.2424L5.75717 12.8282L12.8282 5.75718Z" fill="#2F54EB"/>\n</svg>\n\n\n\n    </div>\n    <div>\n      <h3 class="font-semibold text-gray-900">Works with your data workflows — dbt, metadata sync, and more</h3>\n    </div>\n  </div>\n\n  <div class="border-b border-gray-200 flex gap-5 items-start py-3">\n    <div class="text-blue-600 text-xl">\n<svg width="14" height="14" viewBox="0 0 14 14" fill="none" xmlns="http://www.w3.org/2000/svg">\n<path d="M10.5858 2H7V0H14V7H12V3.41421L3.41421 12H7V14H0V7H2V10.5858L10.5858 2Z" fill="#2F54EB"/>\n</svg>\n\n\n\n    </div>\n    <div>\n      <h3 class="font-semibold text-gray-900">Built to scale with your modern data stack</h3>\n    </div>\n  </div>\n\n  <!-- Footer text -->\n  <div class="pt-10 text-sm">\n   Your data, your infrastructure — Wren AI fits right in.\n  </div>\n</div>\n','\n',char(10)),NULL,'left',NULL,'Data Connectivity & Integrations');
INSERT INTO components_shared_content_blocks VALUES(230,'Ask Questions,  Get Charts without  the BI Learning Curve','Skip complex BI tools. Wren AI lets you ask questions, generate charts, schedule refreshes, and manage databases with natural language in a familiar spreadsheet view.',replace('<div class="space-y-6">\n  <div class="border-b border-gray-200 flex gap-4 items-start py-3">\n    <div class="text-blue-600 text-xl">\n<svg width="18" height="17" viewBox="0 0 18 17" fill="none" xmlns="http://www.w3.org/2000/svg">\n<path d="M0 0H18V2H0V0ZM0 15H18V17H0V15ZM0 10H18V12H0V10ZM0 5H18V7H0V5Z" fill="#2F54EB"/>\n</svg>\n\n\n\n    </div>\n    <div>\n      <h3 class="font-semibold text-gray-900">\n     Ask in plain English to create instant charts and dashboards\n      </h3>\n    </div>\n  </div>\n\n  <div class="border-b border-gray-200 flex gap-5 items-start py-3">\n    <div class="text-blue-600 text-xl">\n<svg width="20" height="20" viewBox="0 0 20 20" fill="none" xmlns="http://www.w3.org/2000/svg">\n<path d="M19.3126 9.17524L17.8984 10.5894L17.1913 9.88234L12.9486 14.1249L12.2415 17.6605L10.8273 19.0747L6.58466 14.832L1.63492 19.7818L0.220703 18.3676L5.17045 13.4178L0.927813 9.17524L2.34202 7.76101L5.87756 7.0539L10.1202 2.81126L9.4131 2.10416L10.8273 0.689941L19.3126 9.17524Z" fill="#2F54EB"/>\n</svg>\n\n\n    </div>\n    <div>\n      <h3 class="font-semibold text-gray-900">Pin reports and schedule cache refreshes for consistent performance</h3>\n    </div>\n  </div>\n\n  <div class="border-b border-gray-200 flex gap-5 items-start py-3">\n    <div class="text-blue-600 text-xl">\n<svg width="20" height="18" viewBox="0 0 20 18" fill="none" xmlns="http://www.w3.org/2000/svg">\n<path d="M1 0C0.44772 0 0 0.44772 0 1V17C0 17.5523 0.44772 18 1 18H19C19.5523 18 20 17.5523 20 17V1C20 0.44772 19.5523 0 19 0H1ZM6 2V5H2V2H6ZM2 11V7H6V11H2ZM2 13H6V16H2V13ZM8 13H18V16H8V13ZM18 11H8V7H18V11ZM18 2V5H8V2H18Z" fill="#2F54EB"/>\n</svg>\n\n\n\n\n    </div>\n    <div>\n      <h3 class=