INSERT INTO components_shared_content_blocks VALUES(231,'Bring Analytics into Your Product Experience.','Deliver interactive dashboards and widgets directly inside your SaaS app, portals, or customer experiences — powered by Wren AI’s white-label analytics platform.',replace('<div class="space-y-6">\n  <div class="border-b border-gray-200 flex gap-4 items-start py-3">\n    <div class="text-blue-600 text-xl">\n<svg width="20" height="18" viewBox="0 0 20 18" fill="none" xmlns="http://www.w3.org/2000/svg">\n<path d="M2 5H18V2H2V5ZM12 16V7H8V16H12ZM14 16H18V7H14V16ZM6 16V7H2V16H6ZM1 0H19C19.5523 0 20 0.44772 20 1V17C20 17.5523 19.5523 18 19 18H1C0.44772 18 0 17.5523 0 17V1C0 0.44772 0.44772 0 1 0Z" fill="#2F54EB"/>\n</svg>\n\n\n\n\n    </div>\n    <div>\n      <h3 class="font-semibold text-gray-900">\n    Fully white-label dashboards aligned with your brand\n      </h3>\n    </div>\n  </div>\n\n  <div class="border-b border-gray-200 flex gap-5 items-start py-3">\n    <div class="text-blue-600 text-xl">\n<svg width="18" height="12" viewBox="0 0 18 12" fill="none" xmlns="http://www.w3.org/2000/svg">\n<path d="M7 12H11V10H7V12ZM0 0V2H18V0H0ZM3 7H15V5H3V7Z" fill="#2F54EB"/>\n</svg>\n\n\n\n    </div>\n    <div>\n      <h3 class="font-semibold text-gray-900">SDKs & low-code embeds for rapid integration</h3>\n    </div>\n  </div>\n\n  <div class="border-b border-gray-200 flex gap-5 items-start py-3">\n    <div class="text-blue-600 text-xl">\n<svg width="24" height="20" viewBox="0 0 24 20" fill="none" xmlns="http://www.w3.org/2000/svg">\n<path d="M5.23379 5.72989C6.65303 3.48625 9.15342 2 12.0002 2C14.847 2 17.3474 3.48625 18.7667 5.72989L20.4569 4.66071C18.6865 1.86199 15.5612 0 12.0002 0C8.43928 0 5.31393 1.86199 3.54356 4.66071L5.23379 5.72989ZM12.0002 18C9.15342 18 6.65303 16.5138 5.23379 14.2701L3.54356 15.3393C5.31393 18.138 8.43928 20 12.0002 20C15.5612 20 18.6865 18.138 20.4569 15.3393L18.7667 14.2701C17.3474 16.5138 14.847 18 12.0002 18ZM12 10C13.6569 10 15 8.6569 15 7