INSERT INTO components_shared_content_blocks VALUES(232,'Built for Enterprise-Grade Control and Flexibility','Wren AI provides secure, governed, and flexible analytics designed to fit directly into your enterprise environment. From identity management to granular data permissions, collaboration, and deployment options, Wren AI gives you control without compromise.',replace('<div class="space-y-6">\n  <div class="border-b border-gray-200 flex gap-4 items-start py-3">\n    <div class="text-blue-600 text-xl">\n  <svg width="19" height="21" viewBox="0 0 19 21" fill="none" xmlns="http://www.w3.org/2000/svg">\n<path d="M15.0003 11V12C15.0003 14.7696 14.3364 17.445 13.0853 19.8455L12.8585 20.2663L11.1116 19.2924C12.2716 17.2115 12.9211 14.8817 12.9935 12.4559L13.0003 12V11H15.0003ZM9.0003 8H11.0003V12L10.9948 12.3787C10.9153 15.1495 9.9645 17.7731 8.3038 19.928L8.073 20.2189L6.52406 18.9536C8.0408 17.0969 8.9145 14.8017 8.9943 12.3663L9.0003 12V8ZM10.0003 4C12.7617 4 15.0003 6.23858 15.0003 9H13.0003C13.0003 7.34315 11.6571 6 10.0003 6C8.3434 6 7.00025 7.34315 7.00025 9V12C7.00025 14.2354 6.1806 16.3444 4.72928 17.9768L4.51767 18.2067L3.06955 16.8273C4.23328 15.6056 4.92099 14.0118 4.99381 12.3027L5.00025 12V9C5.00025 6.23858 7.23883 4 10.0003 4ZM10.0003 0C14.9708 0 19.0003 4.02944 19.0003 9V12C19.0003 13.6979 18.7985 15.3699 18.4035 16.9903L18.2647 17.5285L16.3349 17.0032C16.726 15.5662 16.9475 14.0808 16.9919 12.5684L17.0003 12V9C17.0003 5.13401 13.8662 2 10.0003 2C8.4279 2 6.97663 2.51841 5.80805 3.39364L4.38308 1.96769C5.92267 0.73631 7.87547 0 10.0003 0ZM2.96794 3.38282L4.39389 4.8078C3.5635 5.91652 3.0543 7.27971 3.00431 8.7593L2.99961 8.999L3.00378 11C3.00378 12.1195 2.73991 13.2026 2.24263 14.1772L2.08648 14.4663L0.349609 13.4747C0.728889 12.8103 0.950769 12.0681 0.995389 11.2924L1.00378 11L1.00361 9C1.00025 6.87522 1.73656 4.92242 2.96794 3.38282Z" fill="#2F54EB"/>\n</svg>\n\n\n    </div>\n    <div>\n      <h3 class="font-semibold text-gray-900">\n        Identity Integration\n      </h3>\n      <p class="text-gray-600 text-sm mt-1">\n        Connect with your existing IDP using OIDC\n      </p>\n    </div>\n  </div>\n\n  <div class="border-b border-gray-200 flex gap-5 items-start py-3">\n    <div class="text-blue-600 text-xl">\n    <svg width="20" height="18" viewBox="0 0 20 18" fill="none" xmlns="http://www.w3.org/2000/svg">\n<path d="M1 0C0.44772 0 0 0.44772 0 1V17C0 17.5523 0.44772 18 1 18H19C19.5523 18 20 17.5523 20 17V1C20 0.44772 19.5523 0 19 0H1ZM6 2V5H2V2H6ZM2 11V7H6V11H2ZM2 13H6V16H2V13ZM8 13H18V16H8V13ZM18 11H8V7H18V11ZM18 2V5H8V2H18Z" fill="#2F54EB"/>\n</svg>\n\n    </div>\n    <div>\n      <h3 class="font-semibold text-gray-900">Granular Data Guardrails</h3>\n      <p class="text-gray-600 text-sm mt-1">\n        SQL engine-level enforcement of row-level and column-level controls, plus project-level isolation\n      </p>\n    </div>\n  </div>\n\n  <div class="border-b border-gray-200 flex gap-5 items-start py-3">\n    <div class="text-blue-600 text-xl">\n      <svg width="19" height="18" viewBox="0 0 19 18" fill="none" xmlns="http://www.w3.org/2000/svg">\n<path d="M7.313 8.56548L15.253 0.625488L17.3744 2.74681L15.9602 4.16102L18.0815 6.28234L14.5459 9.81788L12.4246 7.69658L9.4343 10.6869C10.4182 12.5718 10.1186 14.9523 8.5355 16.5354C6.58291 18.488 3.41709 18.488 1.46447 16.5354C-0.488158 14.5828 -0.488158 11.417 1.46447 9.46428C3.04755 7.88128 5.42809 7.58168 7.313 8.56548ZM6.41421 14.4141C7.1953 13.633 7.1953 12.3667 6.41421 11.5857C5.63316 10.8046 4.36684 10.8046 3.58579 11.5857C2.80474 12.3667 2.80474 13.633 3.58579 14.4141C4.36684 15.1951 5.63316 15.1951 6.41421 14.4141Z" fill="#2F54EB"/>\n</svg>\n\n\n    </div>\n    <div>\n      <h3 class="font-semibold text-gray-900">Collaboration Permissions</h3>\n      <p class="text-gray-600 text-sm mt-1">\n        Manage access for dashboards, spreadsheets, and threads\n      </p>\n    </div>\n  </div>\n\n  <div class="border-b border-gray-200 flex gap-5 items-start py-3">\n    <div class="text-blue-600 text-xl">\n<svg width="18" height="18" viewBox="0 0 18 18" fill="none" xmlns="http://www.w3.org/2000/svg">\n<path d="M2 8H16V2H2V8ZM18 1V17C18 17.5523 17.5523 18 17 18H1C0.44772 18 0 17.5523 0 17V1C0 0.44772 0.44772 0 1 0H17C17.5523 0 18 0.44772 18 1ZM16 10H2V16H16V10ZM4 12H7V14H4V12ZM4 4H7V6H4V4Z" fill="#2F54EB"/>\n</svg>\n    </div>\n    <div>\n      <h3 class="font-semibold text-gray-900">Flexible Deployments</h3>\n      <p class="text-gray-600 text-sm mt-1">\n        Run Wren AI in the cloud or self-hosted within your infrastructure\n      </p>\n    </div>\n  </div>\n\n  <div class="border-b border-gray-200 flex gap-5 items-start py-3">\n    <div class="text-blue-600 text-xl">\n<svg width="18" height="18" viewBox="0 0 18 18" fill="none" xmlns="http://www.w3.org/2000/svg">\n<path d="M5 1H18V3H5V1ZM0 0.5H3V3.5H0V0.5ZM0 7.5H3V10.5H0V7.5ZM0 14.5H3V17.5H0V14.5ZM5 8H18V10H5V8ZM5 15H18V17H5V15Z" fill="#2F54EB"/>\n</svg>\n\n    </div>\n    <div>\n      <h3 class="font-semibold text-gray-900">Audit Logging</h3>\n      <p class="text-gray-600 text-sm mt-1">\n        Full visibility into data access and usage across Wren AI\n      </p>\n    </div>\n  </div>\n  <!-- Footer text -->\n  <div class="pt-10 text-sm">\n    Deploy Wren AI with confidence, aligning security, governance, \nand flexibility with your existing data infrastructure.\n  </div>\n</div>\n','\n',char(10)),NULL,'right',NULL,'Security, Governance & Deployment');
INSERT INTO components_pricing_tiers VALUES(1,'Starter','$49','Start Free Trial','#','300 credits included',0,NULL,'Feature-rich entry plan for individuals or small teams to explore GenBI','{"GenBIFeatures":[{"Ask & Follow Up questions":true},{"Report Caching":true},{"Semantic Modeling UI":true},{"Dashboard":true},{"Knowledge Base":true},{"AI-powered Spreadsheets":true},{"Timezone Settings":true}],"DataManagement":[{"Database & Data Warehouse Connectors":true},{"CSV Upload":false},{"CSV Download":true}],"DataSecurity":[{"Row-level Data Control":false},{"Column-level Data Control":false}],"DataVisualizationAndSharing":[{"Charts & Visualizations":true},{"Export as SVG, PNG":true},{"Embedded Charts":false}],"APIManagementAndIntegration":[{"Embedded API":false},{"Token Management":false},{"MCP (Model Context Protocol) Integration":false},{"dbt Integration":false},{"Slack Integration":false},{"Teams Integration":false}],"Boilerplates":[{"SaaS Connector":false},{"Pre-built Metrics":false}],"Organization":[{"Projects":true},{"Members":true},{"Groups":false},{"Auditing Logs":false},{"Usage Management":false}],"Permissions":[{"Role-based Access Control":false},{"Dashboard Permission":false},{"Spreadsheet Permission":false},{"Thread Permission":false}],"SecurityAndSingleSignOn":[{"HIPPA/ BAA (Isolation Instance)":false},{"SOC 2 type 2":false},{"LDAP":false},{"AD Integration":false},{"SSO":false}],"Support":[{"SLA":"Standard"}]}',replace('  <div>\n    <p><strong >Includes:</strong></p>\n  \n   <p style="padding-bottom:10px;padding-top:10px"><strong>GenBI Features</strong></p>\n   <ul style="list-style: none;padding:0">\n      <li>✓ Ask & Follow Up Questions</li>\n      <li>✓ Report Caching</li>\n      <li>✓ Semantic Modeling UI</li>\n      <li>✓ Dashboard</li>\n      <li>✓ Knowledge Base</li>\n      <li>✓ AI-powered Spreadsheets</li>\n      <li>✓ Timezone Settings</li>\n    </ul>\n  \n    <p style="padding-bottom:10px;padding-top:10px"><strong>Data Management</strong></p>\n   <ul style="list-style: none;padding:0">\n      <li>✓ Database & Data Warehouse Connectors</li>\n      <li>✓ CSV Download</li>\n    </ul>\n  \n    <p style="padding-bottom:10px;padding-top:10px"><strong>Data Visualization & Sharing</strong></p>\n   <ul style="list-style: none;padding:0">\n      <li>✓ Charts & Visualizations</li>\n      <li>✓ Export as SVG, PNG</li>\n    </ul>\n  \n    <p style="padding-bottom:10px;padding-top:10px"><strong>Organization</strong></p>\n   <ul style="list-style: none;padding:0">\n      <li>✓ Projects</li>\n      <li>✓ Members</li>\n    </ul>\n  \n    <p style="padding-bottom:10px;padding-top:10px"><strong>Security and Single Sign-on</strong></p>\n   <ul style="list-style: none;padding:0">\n      <li>✓ SOC 2 type 2</li>\n    </ul>\n  \n   <p style="padding-bottom:10px;padding-top:10px"><strong>Support</strong></p>\n   <ul style="list-style: none;padding:0">\n      <li>✓ Standard SLA</li>\n    </ul>\n  </div>\n  ','\n',char(10)));
INSERT INTO components_pricing_tiers VALUES(2,'Essential','$179','Start Free Trial','#','1,100 credits included',1,NULL,'For small teams needing API access, basic controls, and more credits','{"GenBIFeatures":{"Ask & Follow Up questions":true,"Report Caching":true,"Semantic Modeling UI":true,"Dashboard":true,"Knowledge Base":true,"AI-powered Spreadsheets":true,"Timezone Settings":true},"DataManagement":{"Database & Data Warehouse Connectors":true,"CSV Upload":true,"CSV Download":true},"DataSecurity":{"Row-level Data Control":false,"Column-level Data Control":false},"DataVisualizationAndSharing":{"Charts & Visualizations":true,"Export as SVG, PNG":true,"Embedded Charts":false},"APIManagementAndIntegration":{"Embedded API":true,"Token Management":true,"MCP Integration":true,"dbt Integration":false,"Slack Integration":"3 Channels","Teams Integration":"3 Channels (Coming Soon)"},"Boilerplates":{"SaaS Connector":true,"Pre-built Metrics":true},"Organization":{"Projects":true,"Members":true,"Groups":true,"Auditing Logs":true,"Usage Management":true},"Permissions":{"Role-based Access Control":"Basic","Dashboard Permission":true,"Spreadsheet Permission":true,"Thread Permission":true},"SecurityAndSingleSignOn":{"HIPPA/BAA (Isolation Instance)":false,"SOC 2 type 2":true,"LDAP":false,"AD Integration":false,"SSO":false},"Support":{"SLA":"Standard"}}',replace(' <div>\n    <p><strong style="color:#2563eb;">Everything in Starter plan, plus:</strong></p>\n  \n    <p style="padding-bottom:10px;padding-top:10px"><strong>Data Management</strong></p>\n    <ul style="list-style: none;padding:0">\n      <li>✓ CSV Upload</li>\n    </ul>\n  \n    <p style="padding-bottom:10px;padding-top:10px"><strong>API Management & Integration</strong></p>\n    <ul style="list-style: none;padding:0">\n      <li>✓ Embedded API</li>\n      <li>✓ Token Management</li>\n      <li>✓ dbt Integration</li>\n      <li>✓ Slack Integration (3 Channels)</li>\n      <li>✓ Teams Integration <span style="border:1px sol