INSERT INTO components_pricing_frequently_asked_questions VALUES(1,'What cloud region is my organization projects hosted on?',NULL,'All organizations are hosted in GCP’s US-EAST-4 region by default, ensuring performance and reliability. For hosting in a European or other specific region, please contact us via our support portal. We’ll review requests and consider new regions based on demand.');
INSERT INTO components_pricing_frequently_asked_questions VALUES(2,'How are credits calculated for chart, spreadsheet, ask, and follow-up actions? Will I be charged if there’s an error?',NULL,replace('Credits are only deducted when an operation is successfully completed. Actions such as generating charts, using the spreadsheet view, asking questions (Ask), and running follow-up queries all consume credits according to our Credit Pricing Table.\n**Important**: If an action fails or returns an error, no credits will be charged','\n',char(10)));
INSERT INTO components_pricing_frequently_asked_questions VALUES(3,'How are credits used for chart generation?',NULL,replace('When you create a chart in Wren AI Cloud, credits are used for the initial creation.\n\nOnce the chart is generated, you won’t be charged extra credits when viewing it later, such as returning to the chart tab, making adjustments, or regenerating.','\n',char(10)));
INSERT INTO components_pricing_frequently_asked_questions VALUES(10,'Are there any additional fees for using beta features in Wren AI Cloud?',NULL,'Currently, all labeled in beta features in Wren AI Cloud are available at no additional cost. However, we may introduce separate pricing for certain advanced features in the future. We’ll always communicate any changes well in advance to keep you informed.');
INSERT INTO components_pricing_frequently_asked_questions VALUES(15,'What''s the difference between web credits & API credits?',NULL,replace('<div class="space-y-4 text-gray-700 text-sm">\n  <p>\n    <span class="font-bold">Web Credits:</span>\n    Used when you work inside the Wren AI Cloud interface—asking questions,\n    generating charts, execute operations in the Web UI.\n  </p>\n\n  <p>\n    <span class="font-bold">API Credits:</span>\n    Used when your own code or a third-party tool calls Wren AI’s API.\n    Credits are spent for requests your integration sends to our API endpoints.\n  </p>\n</div>\n','\n',char(10)));
INSERT INTO components_pricing_frequently_asked_questions VALUES(31,'Can I switch between monthly and annual billing?',NULL,replace('<div class="space-y-4 text-gray-700 text-sm">\n\n <p>Yes, you can switch between monthly and annual billing, but there are important differences to note:</p>\n  <p>\n    <span class="mr-1">👉</span>\n    <span class="font-bold">Upgrading (Monthly → Annual):</span>\n    You can switch to annual billing at any time by updating your payment method. \n    The change takes effect immediately, granting you access to the annual plan benefits. \n    However, the prorated charge for the upgrade will be applied at the end of your current monthly billing cycle.\n  </p>\n\n  <p>\n    <span class="mr-1">👉</span>\n    <span class="font-bold">Downgrading (Annual → Monthly):</span>\n    You must wait until the end of your current annual billing period before switching to monthly billing. \n    The change will take effect automatically at the start of the next billing cycle, \n    ensuring you retain access to your annual plan benefits for the full duration of the billing period.\n  </p>\n</div>\n','\n',char(10)));
INSERT INTO components_pricing_frequently_asked_questions VALUES(38,'What happens if I exceed the monthly usage limits of my current plan?',NULL,'If you exceed the usage limits for the credits, you need buy additional credits in the billing section.');
INSERT INTO components_pricing_frequently_asked_questions VALUES(39,'What is the difference between Cloud and OSS version?',NULL,'When deciding between Wren AI Cloud and self-hosting the Wren AI Open Source (OSS) version, it''s essential to understand the trade-offs and benefits of each option. Please check out the guidance here!');
INSERT INTO components_pricing_frequently_asked_questions VALUES(40,'Will Wren AI Credits roll over to the next month?',NULL,'If you don’t use all your Wren AI credits in a given month, you can roll them over—up to twice your current monthly plan allowance. However, the roll-over mechanism applies only to monthly plans; unused credits in an annual plan do not roll over across billing cycles.');
INSERT INTO components_pricing_frequently_asked_questions VALUES(50,'How do Wren AI’s Credit reset and billing cycle work?',NULL,replace('<div class="space-y-4 text-gray-700 text-sm">\n <p>At the end of each billing cycle (your subscription period, e.g., monthly or annually), we will reset and recalculate your remaining credits to align with your plan’s renewal:</p>\n  <p>\n    <span class="mr-1">👉</span>\n    <span class="font-bold"> Monthly Plan:</span>\n    Any unused credits will be recalculated and rolled over, up to a maximum of twice your monthly plan allowance.\n  </p>\n\n  <p>\n    <span class="mr-1">👉</span>\n    <span class="font-bold">Annual Plan:</span>\n    Credits do not roll over and will be fully reset at the start of each new billing cycle.\n  </p>\n</div>\n','\n',char(10)));
INSERT INTO components_pricing_frequently_asked_questions VALUES(81,'What type of support do you offer?',NULL,'We provide support via email tickets through our support portal during business hours. For details on our support operations, please refer to our Service Level Agreement.');
INSERT INTO components_pricing_frequently_asked_questions VALUES(82,'What is the relationship between Canner and Wren AI?',NULL,'Wren AI is an AI product by Canner, Inc.');
INSERT INTO components_pricing_frequently_asked_questions VALUES(371,'What cloud region is my organization projects hosted on?',NULL,'All organizations are hosted in GCP’s US-EAST-4 region by default, ensuring performance and reliability. For hosting in a European or other specific region, please contact us via our support portal. We’ll review requests and consider new regions based on demand.');
