INSERT INTO components_home_use_cases_items VALUES(1,'Empower Data Teams with Secure, Scalable Access','Centralized data, delivered everywhere','Data Team','Connect on-prem and cloud databases into a unified semantic layer, enabling secure, governed access without duplication. From dashboards and embedded analytics to conversational AI and MCP clients, empower data-driven insights across the organization while maintaining existing infrastructure and security controls.','topImage');
INSERT INTO components_home_use_cases_items VALUES(2,'Product Analytics, Reimagined with Conversational BI','Test hypotheses, track trends, and boost adoption—without SQL or analyst tickets.','Product Team','Product managers and growth teams connect data, ask questions in plain language, and instantly generate insights. The GenBI engine transforms natural-language queries into accurate SQL and visuals, accelerating decisions and shortening discovery cycles.','bottomImage');
INSERT INTO components_home_use_cases_items VALUES(33,'Executive Insights, Delivered in Plain Language','Explore performance and trends effortlessly—no dashboards or SQL needed.','Executive Non-tech','Wren AI bridges data and decisions. Leaders ask questions in natural language and instantly get accurate charts, summaries, and insights—no BI tool needed. With enterprise-grade governance and semantic modeling, executives can trust every answer and act confidently.','bottomImage');
INSERT INTO components_home_use_cases_items VALUES(37,'Deliver bespoke Insights Instantly to Your VIP Customers','Respond to customer queries faster with data-driven clarity.','Customer Success','Empower Customer Success teams to deliver rapid, personalized insights. Ask questions in plain language and instantly generate charts, summaries, and narratives—no analysts, no delays. Provide VIP customers with data-backed answers that build trust and strengthen relationships at scale.','topImage');
INSERT INTO components_home_use_cases_items VALUES(42,'Wren AI: Your Embedded Analytics Engine','Agencies embed conversational BI to deliver insights faster at scale.','BI Agency','With Wren AI’s Embedded GenBI API, BI agencies embed AI-powered conversational analytics into client tools or workflows. Convert plain-language questions into SQL, charts, and summaries—all white-labeled, scalable, secure, and multi-tenant—without building dashboards','bottomImage');
INSERT INTO components_home_use_cases_items VALUES(43,NULL,NULL,'You could do...',NULL,'topImage');
INSERT INTO components_home_use_cases_items VALUES(68,'Empower Data Teams with Secure, Scalable Access','Centralized data, delivered everywhere','Data Team','Connect on-prem and cloud databases into a unified semantic layer, enabling secure, governed access without duplication. From dashboards and embedded analytics to conversational AI and MCP clients, empower data-driven insights across the organization while maintaining existing infrastructure and security controls.','topImage');
INSERT INTO components_home_use_cases_items VALUES(69,'Product Analytics, Reimagined with Conversational BI','Test hypotheses, track trends, and boost adoption—without SQL or analyst tickets.','Product Team','Product managers and growth teams connect data, ask questions in plain language, and instantly generate insights. The GenBI engine transforms natural-language queries into accurate SQL and visuals, accelerating decisions and shortening discovery cycles.','bottomImage');
